import json
import os

workspace = "/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/held-out-4/play/users/u055/system/state/workspace"
task_id = "task-1e7749a1"
demo_file = os.path.join(workspace, "programs", f"{task_id}.json")

with open(demo_file) as f:
    demos = json.load(f)

input1 = demos[0]["input"]
output1 = demos[0]["output"]
h, w = len(input1), len(input1[0])

def find_border(grid):
    """Find the rectangular border of cells with value 3"""
    r_min, r_max = h, w
    c_min, c_max = h, w
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                r_min = min(r_min, r)
                r_max = max(r_max, r)
                c_min = min(c_min, c)
                c_max = max(c_max, c)
    return r_min, r_max, c_min, c_max

def find_center(grid, r_min, r_max, c_min, c_max):
    """Find the center of the interior"""
    return (r_min + r_max) // 2, (c_min + c_max) // 2

def manhattan_dist(r, c, center):
    return abs(r - center[0]) + abs(c - center[1])

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find border
    r_min, r_max, c_min, c_max = find_border(grid)
    if r_min == h or c_min == w:
        return grid  # No border

    # Find center
    center_r, center_c = find_center(grid, r_min, r_max, c_min, c_max)

    # Create output grid (copy of input)
    result = [row[:] for row in grid]

    # Fill interior
    for r in range(h):
        for c in range(w):
            # Only fill interior cells (inside the border)
            if r < r_min + 1 or r >= r_max - 1 or c < c_min + 1 or c >= c_max - 1:
                continue
            if grid[r][c] == 3 or grid[r][c] == 0:
                # Check if sheed (3) or not, and apply color based on manhattan from center
                if grid[r][c] == 3:
                    result[r][c] = 3
                else:
                    d = manhattan_dist(r, c, (center_r, center_c))
                    # Pattern: d=0 -> 3 (seed), d=1 -> 4, d=2 -> 2, d=3 -> 4, d=4 -> 4, ...
                    # Actually pattern from demo: center=3, then 4, 2, 4, 4, 2, 2, 2, 2, 2
                    if d == 0:
                        result[r][c] = 3  # center seed
                    elif d == 1:
                        result[r][c] = 4
                    elif d == 2:
                        result[r][c] = 2
                    elif d == 3:
                        result[r][c] = 4
                    elif d == 4:
                        result[r][c] = 4
                    else:
                        # For d > 4, it depends on direction from center
                        # Continue implementing based on observed pattern
                        result[r][c] = 4

            # Leave 0 cells as 0 and 3 border as is
            elif grid[r][c] == 0:
                result[r][c] = 0

    return result

# Test
