center_c = sum(s[1] for s in seeds) // len(seeds)
print(f"Center: ({center_r}, {center_c})")

# Now compute original transformation for interior
# Try: color based on manhattan from nearest seed

def manhattan_to_nearest_seed(r, c, seeds):
    if not seeds:
        return float('inf')
    return min(abs(r - s[0]) + abs(c - s[1]) for s in seeds)

# Build new transformation
